import type { ApplicantType } from '@/features/leave/types';

/**
 * Leave seed for the development mock.
 *
 * Leave types only. Applications are generated by `devApi` against the live
 * student, teacher and staff rosters — an application hard-coded to a person
 * id would break the moment a roster seed moved, and a teacher applying for
 * study leave they are not entitled to would be worse than useless.
 *
 * The set is deliberately uneven so every rule in the module is reachable
 * without editing anything: one type with no quota at all (student leave),
 * one that may be backdated and one that may not, one unpaid, one needing a
 * document, one capped at a short stretch, and one retired.
 */

export interface LeaveTypeSeed {
  id: number;
  name: string;
  code: string;
  applies_to: ApplicantType[];
  annual_quota: number | null;
  is_paid: boolean;
  requires_document: boolean;
  allows_backdated: boolean;
  max_consecutive_days: number | null;
  is_active?: boolean;
}

