/**
 * Shapes of application the generator lays down, as offsets from today.
 *
 * Spread either side of today on purpose: something decided and finished,
 * something running right now (so the "away today" list is never empty),
 * something approved but not yet begun (so an approval can be undone), and a
 * pending one whose first day has already passed — the row the register
 * shouts about, because somebody is absent that nobody has accounted for.
 */
export interface ApplicationShape {
  /** Days from today; negative is in the past. */
  fromOffset: number;
  /** Length in calendar days, inclusive. */
  span: number;
  status: 'pending' | 'approved' | 'rejected' | 'cancelled' | 'withdrawn';
  half?: 'first_half' | 'second_half';
  reason: string;
  document?: string;
  note?: string;
}

